  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.weather",
        "abilityName": "com.huawei.weather.MainAbility",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
